//! The tray icon.
//!
//! Glyphi keeps running when the window is closed — that is what makes a
//! once-an-hour scan possible without a visible app — so the tray is the only way
//! back to it. The menu deliberately holds three items: a tray menu with fifteen
//! entries is a settings page nobody asked for.

use tray_icon::menu::{Menu, MenuEvent, MenuItem, PredefinedMenuItem};
use tray_icon::{Icon, TrayIcon, TrayIconBuilder};

/// The tray artwork: 32×32, four bytes per pixel, generated by hand and embedded.
///
/// Embedded rather than staged next to the binary because it is 4 KiB and a missing
/// file would cost the tray silently — there is nothing in the window to notice it
/// from. `include_bytes!` also means the packaged app needs no resource directory.
const ICON: &[u8] = include_bytes!("../assets/tray-32.rgba");
const ICON_SIZE: u32 = 32;

/// What the user picked in the tray.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TrayCommand {
    ShowDashboard,
    ShowMiniWindow,
    Refresh,
    Quit,
}

pub struct Tray {
    icon: TrayIcon,
    show_dashboard: MenuItem,
    show_mini: MenuItem,
    refresh: MenuItem,
    quit: MenuItem,
}

impl Tray {
    /// Builds the icon and its menu.
    pub fn new(tooltip: &str) -> Result<Self, String> {
        let icon = Icon::from_rgba(ICON.to_vec(), ICON_SIZE, ICON_SIZE)
            .map_err(|error| error.to_string())?;

        let menu = Menu::new();
        let show_dashboard = MenuItem::new("Open Glyphi", true, None);
        let show_mini = MenuItem::new("Mini window", true, None);
        let refresh = MenuItem::new("Refresh now", true, None);
        let quit = MenuItem::new("Quit Glyphi", true, None);
        let separator = PredefinedMenuItem::separator();

        menu.append_items(&[&show_dashboard, &show_mini, &separator, &refresh, &quit])
            .map_err(|error| error.to_string())?;

        let icon = TrayIconBuilder::new()
            .with_tooltip(tooltip)
            .with_icon(icon)
            .with_menu(Box::new(menu))
            .build()
            .map_err(|error| error.to_string())?;

        Ok(Self {
            icon,
            show_dashboard,
            show_mini,
            refresh,
            quit,
        })
    }

    /// Reads the menu channel once. Called from the event loop, never from a worker:
    /// the tray owns platform handles that belong to the main thread.
    pub fn poll(&self) -> Option<TrayCommand> {
        while let Ok(event) = MenuEvent::receiver().try_recv() {
            if event.id == self.show_dashboard.id() {
                return Some(TrayCommand::ShowDashboard);
            }
            if event.id == self.show_mini.id() {
                return Some(TrayCommand::ShowMiniWindow);
            }
            if event.id == self.refresh.id() {
                return Some(TrayCommand::Refresh);
            }
            if event.id == self.quit.id() {
                return Some(TrayCommand::Quit);
            }
        }
        None
    }

    /// Changes the tooltip, which is the cheapest way to say "scanning" without a
    /// notification the user did not ask for.
    pub fn set_tooltip(&self, tooltip: &str) {
        let _ = self.icon.set_tooltip(Some(tooltip));
    }
}
